<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiRequest } from './api'
type App={id:string;name:string;version:string;description:string;category:string;status:string}
type Plugin={id:string;name:string;version:string;description:string;plugin_type:string}
const apps=ref<App[]>([]),plugins=ref<Plugin[]>([]),error=ref(''),loading=ref(false),source=ref(''),installing=ref(false),notice=ref('')
async function refresh(){loading.value=true;try{const [pawapps,installed]=await Promise.all([apiRequest<{apps:App[]}>('/pawapps'),apiRequest<Plugin[]>('/plugins')]);apps.value=pawapps.apps;plugins.value=installed;error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'Could not load apps.'}finally{loading.value=false}}
async function remove(app:App){if(!window.confirm(`Uninstall ${app.name}?`))return;try{await apiRequest(`/pawapps/${encodeURIComponent(app.id)}`,{method:'DELETE'});await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not uninstall app.'}}
async function install(){if(!source.value.trim())return;installing.value=true;error.value='';notice.value='';try{const result=await apiRequest<{name:string}>('/plugins/install',{method:'POST',body:JSON.stringify({source:source.value.trim()})});source.value='';notice.value=`Installed ${result.name || 'plugin'}.`;await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not install plugin.'}finally{installing.value=false}}
async function removePlugin(plugin:Plugin){if(!window.confirm(`Uninstall ${plugin.name}?`))return;try{await apiRequest(`/plugins/${encodeURIComponent(plugin.id)}`,{method:'DELETE'});await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not uninstall plugin.'}}
onMounted(()=>void refresh())
</script>
<template><section class="settings-page"><header class="settings-heading"><div><p class="eyebrow">APP CENTER</p><h1>Apps</h1></div><button @click="refresh">Refresh</button></header><p v-if="error" class="inline-error">{{error}}</p><p v-if="notice" class="success-notice">{{notice}}</p><div class="settings-card"><h2>PawApps</h2><p v-if="loading">Loading apps…</p><p v-else-if="!apps.length">No PawApps installed.</p><div v-for="app in apps" :key="app.id" class="skills-item"><span><strong>{{app.name}}</strong><small>{{app.category||'App'}} · {{app.version}} · {{app.description}}</small></span><button @click="remove(app)">Uninstall</button></div></div><div class="settings-card"><h2>Plugins</h2><form class="skills-editor-actions" @submit.prevent="install"><input v-model="source" aria-label="Plugin source" placeholder="Local directory, ZIP file, or HTTPS URL"/><button type="submit" :disabled="installing">{{installing?'Installing…':'Install plugin'}}</button></form><p v-if="!plugins.length" class="muted">No plugins installed.</p><div v-for="plugin in plugins" :key="plugin.id" class="skills-item"><span><strong>{{plugin.name}}</strong><small>{{plugin.plugin_type||'Plugin'}} · {{plugin.version}} · {{plugin.description}}</small></span><button @click="removePlugin(plugin)">Uninstall</button></div></div></section></template>
